package com.example.editor.remote.auth.provider;

import java.net.URI;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.time.Instant;
import org.springframework.stereotype.Component;
import com.example.editor.remote.auth.*;
import com.example.editor.remote.storage.RemoteStorageProperties;
import com.example.editor.remote.storage.RemoteStorageProviderType;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

/** Microsoft identity platform Authorization Code + PKCE para OneDrive/Graph. */
@Component
public class MicrosoftOneDriveOAuthProvider implements RemoteOAuthProvider {
    private final RemoteOAuthHttpClient http;private final ObjectMapper mapper;
    /** Descripción: Inicializa una instancia de MicrosoftOneDriveOAuthProvider con sus dependencias y datos de entrada. Entradas: http: dato de entrada necesario para la operación; mapper: componente de conversión utilizado durante el procesamiento. Salida: deja la instancia inicializada y lista para su uso. */ public MicrosoftOneDriveOAuthProvider(RemoteOAuthHttpClient http,ObjectMapper mapper){this.http=http;this.mapper=mapper;}
    /** Descripción: Ejecuta la operación «type» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteStorageProviderType type(){return RemoteStorageProviderType.ONEDRIVE;}
    /** Descripción: Ejecuta la operación «scopes» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public List<String> scopes(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth){
        if(storage.isOneDriveAppFolder())return List.of("offline_access","Files.ReadWrite.AppFolder");
        return auth.getScopes().isEmpty()?List.of("offline_access","Files.ReadWrite"):List.copyOf(auth.getScopes());
    }
    /** Descripción: Ejecuta la operación «useDeviceFlow» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ @Override public boolean useDeviceFlow(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth){requireClient(auth);return auth.isDeviceFlowPreferred();}
    /** Descripción: Ejecuta la operación «beginDeviceAuthorization» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteDeviceAuthorization beginDeviceAuthorization(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("scope",String.join(" ",scopes));
        JsonNode json=parseMicrosoftResponse(http.postForm(URI.create(endpoint(auth.getDeviceAuthorizationUrl(),auth)),values,Map.of()),"Microsoft device authorization");
        String deviceCode=json.path("device_code").asText("");String userCode=json.path("user_code").asText("");String verification=json.path("verification_uri_complete").asText("");if(verification.isBlank())verification=json.path("verification_uri").asText("");long expires=Math.max(1L,json.path("expires_in").asLong(900L));int interval=Math.max(5,json.path("interval").asInt(5));
        if(deviceCode.isBlank()||userCode.isBlank()||verification.isBlank())throw new RemoteAuthException(RemoteAuthException.Reason.TOKEN_EXCHANGE_FAILED,"Microsoft device authorization returned an incomplete response");
        return new RemoteDeviceAuthorization(deviceCode,userCode,RemoteNetworkPolicy.requireHttps(URI.create(verification)),Instant.now().plusSeconds(expires),interval);
    }
    /** Descripción: Ejecuta la operación «pollDeviceAuthorization» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; deviceCode: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteDevicePollResult pollDeviceAuthorization(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String deviceCode,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("device_code",deviceCode);values.put("grant_type","urn:ietf:params:oauth:grant-type:device_code");values.put("scope",String.join(" ",scopes));
        RemoteOAuthHttpClient.Response response=http.postForm(URI.create(endpoint(auth.getTokenUrl(),auth)),values,Map.of());JsonNode json=parseDeviceResponse(response);String error=json.path("error").asText("");
        if(error.isBlank()){RemoteCredentialMaterial token=RemoteOAuthJsonSupport.token(type(),json,scopes,"","");return RemoteDevicePollResult.authorized(account(auth,token));}
        int interval=Math.max(5,json.path("interval").asInt(5));
        return switch(error){case "authorization_pending"->RemoteDevicePollResult.pending(interval);case "slow_down"->RemoteDevicePollResult.slowDown(interval+5);case "authorization_declined","access_denied"->RemoteDevicePollResult.denied();case "expired_token","bad_verification_code"->RemoteDevicePollResult.expired();default->{String detail=RemoteSecretRedactor.redact(json.path("error_description").asText(error));RemoteAuthException configuration=microsoftConfigurationError(detail);if(configuration!=null)throw configuration;throw new RemoteAuthException(RemoteAuthException.Reason.TOKEN_EXCHANGE_FAILED,"Microsoft device authorization failed: "+detail);}};
    }
    /** Descripción: Ejecuta la operación «authorizationUri» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; redirect: dato de entrada necesario para la operación; state: dato de entrada necesario para la operación; challenge: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public URI authorizationUri(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String redirect,String state,String challenge,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("response_type","code");values.put("redirect_uri",redirect);values.put("response_mode","query");values.put("scope",String.join(" ",scopes));values.put("state",state);values.put("code_challenge",challenge);values.put("code_challenge_method","S256");values.put("prompt","select_account");
        return URI.create(endpoint(auth.getAuthorizationUrl(),auth)+"?"+RemoteOAuthJsonSupport.query(values));
    }
    /** Descripción: Ejecuta la operación «exchange» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; redirect: dato de entrada necesario para la operación; code: dato de entrada necesario para la operación; verifier: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteCredentialMaterial exchange(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String redirect,String code,String verifier,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("grant_type","authorization_code");values.put("code",code);values.put("redirect_uri",redirect);values.put("code_verifier",verifier);values.put("scope",String.join(" ",scopes));if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());
        JsonNode json=parseMicrosoftResponse(http.postForm(URI.create(endpoint(auth.getTokenUrl(),auth)),values,Map.of()),"Microsoft token exchange");return account(auth,RemoteOAuthJsonSupport.token(type(),json,scopes,"",""));
    }
    /** Descripción: Ejecuta la operación «refresh» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; current: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteCredentialMaterial refresh(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial current){
        if(!current.refreshable())return current;requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("grant_type","refresh_token");values.put("refresh_token",current.refreshToken());values.put("scope",String.join(" ",current.scopes()));if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());
        JsonNode json=parseMicrosoftResponse(http.postForm(URI.create(endpoint(auth.getTokenUrl(),auth)),values,Map.of()),"Microsoft token refresh");RemoteCredentialMaterial token=RemoteOAuthJsonSupport.token(type(),json,current.scopes(),current.accountId(),current.accountLabel());if(token.refreshToken().isBlank())token=new RemoteCredentialMaterial(type(),token.accessToken(),current.refreshToken(),token.tokenType(),token.expiresAt(),token.scopes(),current.accountId(),current.accountLabel(),token.issuedAt());return token;
    }
    /** Descripción: Ejecuta la operación «revoke» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; current: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ @Override public void revoke(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial current){/* Microsoft has no per-application OAuth token revocation endpoint; local deletion is authoritative for HYDRA. */}
    /** Descripción: Ejecuta la operación «parseDeviceResponse» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: response: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private JsonNode parseDeviceResponse(RemoteOAuthHttpClient.Response response){try{return mapper.readTree(response.body());}catch(tools.jackson.core.JacksonException exception){throw new RemoteAuthException(RemoteAuthException.Reason.TOKEN_EXCHANGE_FAILED,"Microsoft device authorization returned invalid JSON",exception);}}
    /** Descripción: Ejecuta la operación «parseMicrosoftResponse» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: response: dato de entrada necesario para la operación; operation: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private JsonNode parseMicrosoftResponse(RemoteOAuthHttpClient.Response response,String operation){
        if(response.successful())return parseDeviceResponse(response);
        String safe=response.safeText();RemoteAuthException configuration=microsoftConfigurationError(safe);if(configuration!=null)throw configuration;
        throw new RemoteAuthException(RemoteAuthException.Reason.TOKEN_EXCHANGE_FAILED,operation+" failed with HTTP "+response.statusCode()+": "+safe);
    }
    /** Descripción: Ejecuta la operación «microsoftConfigurationError» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: detail: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private RemoteAuthException microsoftConfigurationError(String detail){
        if(detail.contains("AADSTS50059"))return new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"Microsoft could not identify the organization for this application. In Installation setup, choose the Microsoft account type that matches the Entra app. If the app is limited to one organization, choose Only this organization and enter its organization directory ID or verified domain from the Entra Overview page.");
        if(detail.contains("AADSTS50194"))return new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"The Microsoft application is registered for one organization, but the connection is using a shared Microsoft sign-in mode. In Installation setup, choose Only this organization and enter its organization directory ID or verified domain, or change the Entra app to accept accounts from several organizations.");
        if(detail.contains("AADSTS90002"))return new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"The configured Microsoft organization was not found. Check the organization directory ID or verified organization domain in Installation setup and copy it from the Entra application Overview page.");
        return null;
    }
    /** Descripción: Ejecuta la operación «account» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: auth: dato de entrada necesario para la operación; token: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private RemoteCredentialMaterial account(RemoteAuthProperties.Provider auth,RemoteCredentialMaterial token){JsonNode json=RemoteOAuthJsonSupport.parse(mapper,http.get(URI.create(auth.getAccountUrl()),Map.of("Authorization","Bearer "+token.accessToken())),"Microsoft account lookup");String label=json.path("displayName").asText("");if(label.isBlank())label=json.path("userPrincipalName").asText("Microsoft account");return RemoteOAuthJsonSupport.withAccount(token,json.path("id").asText(""),label);}
    /** Descripción: Resuelve el endpoint configurado mediante las variables del contrato actual. Entradas: configured: URL configurada; auth: configuración OAuth actual. Salida: devuelve el endpoint resuelto sin aplicar reparaciones históricas. */
    /** Descripción: Ejecuta la operación «endpoint» correspondiente a la responsabilidad de MicrosoftOneDriveOAuthProvider. Entradas: configured: configuración que gobierna el comportamiento; auth: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String endpoint(String configured, RemoteAuthProperties.Provider auth) {
        String organization = auth.getTenant().isBlank() ? "common" : auth.getTenant().trim();
        return RemoteOAuthJsonSupport.template(configured, organization, auth.getClientId());
    }
    /** Descripción: Valida las condiciones necesarias para «requireClient» y rechaza entradas no válidas. Entradas: auth: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void requireClient(RemoteAuthProperties.Provider auth){if(auth==null||!auth.isEnabled()||auth.getClientId().isBlank())throw new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"Microsoft OAuth requires a configured Application (client) ID");}
}
